INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(6217316, 918721, 114285, '<td valign="top">Gorgeous, shots. 10</td>', 'Gorgeous, shots. 10', '2010-11-09 01:41:34.000000', NULL, 1),
(6217317, 918727, 114285, '<td valign="top">Too sweet. 10</td>', 'Too sweet. 10', '2010-11-09 01:43:35.000000', NULL, 1),
(6217330, 918646, 122131, '<td valign="top">I''d say this will be a big contender for a ribbon.<br/>The only issue I have with it is the ''runner'' in the shot, and the appearance of water being thrown at him from behind.<br/>I understand the water on the swimmer, and the sweat coming out of the biker, but having had been part of marathons, I''d say I would be rather annoyed if someone followed me with a bucket of water..<br/>Still, you have stopped the motion of the water which gives the photo great dynamics. 9 from me.</td>', 'I''d say this will be a big contender for a ribbon.The only issue I have with it is the ''runner'' in the shot, and the appearance of water being thrown at him from behind.I understand the water on the swimmer, and the sweat coming out of the biker, but having had been part of marathons, I''d say I would be rather annoyed if someone followed me with a bucket of water..Still, you have stopped the motion of the water which gives the photo great dynamics. 9 from me.', '2010-11-09 03:49:21.000000', NULL, 1),
